@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#0b1014;--panel:#11191e;--panel2:#172126;--line:#29363b;--muted:#87979a;--text:#e7eee9;--mint:#b6edc7;--gold:#edc477;--red:#e77b73;--blue:#8ebdf2}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% 40%,#172329 0%,var(--bg) 72%);color:var(--text);font:14px Manrope,system-ui,sans-serif;min-height:100vh}button,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible{outline:2px solid var(--mint);outline-offset:3px}.app{max-width:1480px;margin:auto;padding:20px 24px 24px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:14px}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:37px;height:37px;border:1px solid #52695d;border-radius:12px;display:grid;place-items:center;color:var(--mint);font-size:21px;background:linear-gradient(145deg,#22362d,#121d1b)}.brand h1{font-size:15px;letter-spacing:.13em;margin:0;font-weight:800}.brand small{display:block;color:var(--muted);font:10px 'DM Mono',monospace;letter-spacing:.12em;margin-top:3px}.top-meta{display:flex;align-items:center;gap:10px}.pill{border:1px solid var(--line);border-radius:999px;padding:8px 12px;color:#b5c3be;font:10px 'DM Mono',monospace;letter-spacing:.08em;background:#10171a}.online-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#76d69b;margin-right:6px;box-shadow:0 0 10px #76d69b66}.layout{display:grid;grid-template-columns:244px minmax(360px,1fr) 260px;gap:14px;align-items:stretch}.panel{background:linear-gradient(155deg,#131c20f2,#10171bed);border:1px solid var(--line);border-radius:13px;box-shadow:0 14px 40px #0002}.profile,.right-rail{padding:16px}.panel-heading{font:10px 'DM Mono',monospace;letter-spacing:.15em;color:#aab8b2;display:flex;justify-content:space-between;align-items:center}.dots{color:#758580;letter-spacing:3px}.portrait{height:133px;margin:14px 0 14px;border:1px solid #32413d;border-radius:9px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 30%,#466854 0,#22382e 35%,#15221e 71%,#111918 100%);display:grid;place-items:center}.portrait:before,.portrait:after{content:'';position:absolute;border:1px solid #a9d8b333;transform:rotate(45deg);width:80px;height:80px;top:-37px;left:-30px}.portrait:after{width:120px;height:120px;top:80px;left:174px}.portrait-glow{position:absolute;width:100px;height:100px;border-radius:50%;background:#d7f0d51c;filter:blur(20px)}#portraitIcon{font-size:56px;z-index:1;filter:drop-shadow(0 5px 10px #06120c)}.portrait-label{position:absolute;z-index:2;bottom:0;left:0;right:0;padding:24px 11px 9px;background:linear-gradient(transparent,#0b1412e8)}.portrait-label strong{display:block;font-size:13px}.portrait-label small{display:block;color:#a8c0b0;font:9px 'DM Mono',monospace;letter-spacing:.14em;margin-top:3px}.level-row,.xp-label{display:flex;justify-content:space-between;font:10px 'DM Mono',monospace;color:#a8b7b0;letter-spacing:.08em}.level-row b{color:var(--text);font-size:12px;margin-left:4px}.level-row span:last-child{color:var(--gold);font-size:9px}.xp-track,.bar{height:5px;border-radius:6px;background:#283337;overflow:hidden}.xp-track{margin:8px 0 5px}.xp-track i{display:block;width:0;height:100%;background:linear-gradient(90deg,#84c99d,#d2e8a9);box-shadow:0 0 10px #9dddb777;transition:width .25s}.xp-label{font-size:8px;color:#778780}.vitals{display:grid;gap:12px;border-top:1px solid #263237;border-bottom:1px solid #263237;margin:15px 0;padding:13px 0}.vitals label{font:8px 'DM Mono',monospace;letter-spacing:.12em;color:#869791}.vitals b{float:right;font:9px 'DM Mono',monospace;color:#c5d2ca}.bar{height:4px;margin-top:7px}.bar i{display:block;width:100%;height:100%;background:#d58076;transition:width .2s}.bar.blue i{background:#83b8e4}.section-title{font:9px 'DM Mono',monospace;letter-spacing:.13em;color:#92a39c;display:flex;justify-content:space-between;align-items:center;margin:15px 0 9px}.tiny-button{border:1px solid #33413f;background:#17211f;border-radius:5px;padding:4px 7px;color:#9eb8a5;font:8px 'DM Mono',monospace;letter-spacing:.06em}.attributes{display:grid;grid-template-columns:1fr 1fr;gap:6px}.attributes div{padding:8px 9px;background:#172024;border:1px solid #263338;border-radius:6px;display:flex;justify-content:space-between;font:10px 'DM Mono',monospace;color:#849690}.attributes b{color:#e2ebe5}.relic{display:flex;align-items:center;gap:9px;padding:9px;background:#171d1c;border:1px solid #39382d;border-radius:7px}.relic-icon{width:27px;height:27px;border-radius:6px;background:#3c3420;color:var(--gold);display:grid;place-items:center}.relic b,.relic small{display:block}.relic b{font-size:10px}.relic small{font:8px 'DM Mono',monospace;color:#c2a86c;margin-top:3px}.class-switch{display:flex;align-items:center;gap:8px;margin-top:13px}.class-switch label{font:8px 'DM Mono',monospace;color:#899b94;letter-spacing:.1em}.class-switch select{flex:1;background:#172024;border:1px solid #2a393c;padding:7px;border-radius:5px;font-size:10px}.world{display:flex;flex-direction:column;overflow:hidden;min-height:590px}.world-head{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;border-bottom:1px solid #273337}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.12em;color:#95a59c}.eyebrow span{color:var(--gold);padding:0 4px}.world-head h2{margin:4px 0 0;font-size:18px;letter-spacing:-.03em}.icon-button{width:30px;height:30px;border-radius:7px;background:#182125;border:1px solid #344044;color:#a3b2ac}.canvas-wrap{position:relative;flex:1;min-height:430px;background:#18231f;overflow:hidden}canvas{display:block;width:100%;height:100%;touch-action:none}.world-tag{position:absolute;left:14px;top:13px;padding:7px 9px;border:1px solid #9eb99b33;border-radius:5px;background:#101917aa;color:#b6c7b7;font:8px 'DM Mono',monospace;letter-spacing:.09em;pointer-events:none}.world-tag i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#9cd296;margin-right:5px}.toast{position:absolute;top:13px;left:50%;transform:translateX(-50%);background:#101917d9;border:1px solid #758f7540;border-radius:5px;padding:8px 12px;color:#c5d5c8;font:9px 'DM Mono',monospace;opacity:0;transition:opacity .2s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1}.touch-hint{display:none;position:absolute;bottom:12px;left:50%;transform:translateX(-50%);font:8px 'DM Mono',monospace;color:#c0d0c488;white-space:nowrap;pointer-events:none}.world-footer{height:39px;border-top:1px solid #273337;display:flex;align-items:center;justify-content:space-between;padding:0 16px;color:#81918b;font:8px 'DM Mono',monospace;letter-spacing:.07em}.world-footer b{color:#d8e2d9;font-weight:500}.world-footer i{font-style:normal;color:var(--gold);padding:0 4px}.live{color:#92d2a2;font-size:8px}.quest{margin:13px 0 15px;padding:11px 10px;background:linear-gradient(135deg,#1d2b27,#18211f);border:1px solid #33443b;border-radius:8px;display:grid;grid-template-columns:28px 1fr;gap:9px}.quest-icon{width:26px;height:26px;border-radius:6px;background:#263b30;color:#b8e0b6;display:grid;place-items:center}.quest-copy small,.arena-card small{font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#a5bb9c}.quest-copy h3{margin:4px 0;font-size:12px}.quest-copy p{margin:0;color:#9aa9a2;font-size:9px;line-height:1.55}.quest-progress{grid-column:1/3;display:flex;align-items:center;gap:8px;font:8px 'DM Mono',monospace;color:#9aac9e}.quest-progress .bar{flex:1;margin:0}.quest-progress .bar i{background:#98d19f;width:0}.reward{grid-column:1/3;padding-top:8px;border-top:1px solid #334039;font:8px 'DM Mono',monospace;color:#788982}.reward b{color:var(--gold);margin-left:5px}.reward span{float:right}.points{color:#c7a86c;font-size:8px}.skill-list{display:grid;gap:6px}.skill{display:grid;grid-template-columns:28px 1fr auto;align-items:center;gap:8px;padding:8px;background:#171f22;border:1px solid #2b383b;border-radius:7px}.skill-key{width:26px;height:26px;display:grid;place-items:center;border:1px solid #4a5b52;border-radius:6px;color:#bdd8bf;background:#1e2b25;font:10px 'DM Mono',monospace}.skill b{display:block;font-size:9px}.skill small{display:block;font:8px 'DM Mono',monospace;color:#80918a;margin-top:3px}.cooldown{font:8px 'DM Mono',monospace;color:#81928a}.skill.ready .cooldown{color:#bce6c2}.loot-title{margin-top:16px}.loot-list{display:grid;gap:5px;max-height:86px;overflow:auto}.loot-item{display:flex;justify-content:space-between;align-items:center;padding:7px 8px;border:1px solid #303638;background:#191e20;border-radius:5px;font-size:9px}.loot-item small{font:8px 'DM Mono',monospace;color:#8c9a94}.rarity-common{color:#d5ddd7}.rarity-uncommon{color:#7fd59b}.rarity-rare{color:#8ab9f3}.rarity-mythic{color:#ca9bf2}.rarity-legendary{color:#efc56f}.rarity-ancient{color:#f18a75}.rarity-celestial{color:#f1a9de}.empty{font-size:9px;color:#75837e;padding:5px 1px}.arena-card{margin-top:13px;border:1px solid #373731;background:linear-gradient(110deg,#25251f,#191d1b);border-radius:7px;padding:9px;display:flex;align-items:center;gap:8px}.arena-symbol{width:27px;height:27px;border-radius:6px;background:#373322;color:#c9ae6a;display:grid;place-items:center}.arena-card div:nth-child(2){flex:1}.arena-card b,.arena-card span{display:block}.arena-card b{font-size:9px;margin:3px 0}.arena-card span{color:#89928b;font-size:8px}.arena-card .lock{color:#a39770;font-size:13px}.controls{height:44px;display:flex;align-items:center;gap:20px;padding:0 8px}.control-tip{display:flex;align-items:center;gap:3px}.control-tip kbd{background:#182024;border:1px solid #344043;border-bottom-width:2px;border-radius:4px;padding:3px 5px;color:#b8c5bd;font:8px 'DM Mono',monospace}.control-tip span{font:8px 'DM Mono',monospace;color:#778780;margin-left:4px;letter-spacing:.06em}.footer-note{margin-left:auto;font:8px 'DM Mono',monospace;color:#596861;letter-spacing:.08em}.modal-backdrop{position:fixed;inset:0;background:#050909c9;display:grid;place-items:center;padding:20px;z-index:5;backdrop-filter:blur(8px)}.modal-backdrop[hidden]{display:none}.modal{width:min(410px,100%);padding:28px;background:linear-gradient(145deg,#1b2924,#11191b);border:1px solid #526a57;border-radius:14px;text-align:center;box-shadow:0 24px 100px #0009}.modal-kicker{font:9px 'DM Mono',monospace;color:#a8ceab;letter-spacing:.16em}.modal-symbol{margin:13px auto 4px;width:42px;height:42px;display:grid;place-items:center;border:1px solid #72896a;border-radius:50%;color:#e3cb87;font-size:20px}.modal h2{font-size:27px;margin:5px 0}.modal p{font-size:11px;color:#a1b0a7;margin:5px 0 19px}.attribute-choices{display:grid;grid-template-columns:1fr 1fr;gap:8px}.attribute-choice{border:1px solid #374740;background:#192321;padding:11px;border-radius:7px;text-align:left}.attribute-choice:hover{border-color:#9ccc9e;background:#213129}.attribute-choice b{display:block;font-size:11px}.attribute-choice small{display:block;color:#91a299;font-size:9px;margin-top:4px}.continue{width:100%;margin-top:16px;border:0;border-radius:7px;background:#b8e3b9;color:#122018;padding:11px;font:10px 'DM Mono',monospace;letter-spacing:.08em;font-weight:500}.continue span{float:right}
@media(max-width:1050px){.layout{grid-template-columns:220px minmax(320px,1fr)}.right-rail{grid-column:1/-1;display:grid;grid-template-columns:1fr 1.1fr;gap:0 18px}.right-rail>.panel-heading,.right-rail>.quest,.right-rail>.arena-card{grid-column:1}.right-rail>.section-title,.right-rail>.skill-list,.right-rail>.loot-title,.right-rail>.loot-list{grid-column:2}.right-rail>.section-title:first-of-type{grid-row:1}.right-rail>.quest{grid-row:2/6}.right-rail>.arena-card{grid-row:6}.right-rail>.skill-list{grid-row:2/4}.right-rail>.loot-title{grid-row:4}.right-rail>.loot-list{grid-row:5}.right-rail>.panel-heading{grid-column:1/-1}.world{min-height:550px}}@media(max-width:680px){.app{padding:12px}.topbar{margin-bottom:10px}.brand h1{font-size:12px}.brand small{font-size:8px}.pill{padding:7px 8px;font-size:8px}.pill:nth-child(2){display:none}.layout{display:flex;flex-direction:column}.world{order:0;min-height:56vh}.canvas-wrap{min-height:350px}.profile{order:1}.right-rail{order:2;display:block}.portrait{height:115px}.world-footer{font-size:7px;padding:0 9px}.world-footer span:last-child{display:none}.touch-hint{display:block}.controls{gap:7px;justify-content:space-between;flex-wrap:wrap;height:auto;padding:11px 0}.control-tip kbd{font-size:7px;padding:3px}.control-tip span{font-size:7px}.footer-note{display:none}.profile{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.profile>.panel-heading,.profile>.portrait,.profile>.level-row,.profile>.xp-track,.profile>.xp-label,.profile>.vitals,.profile>.class-switch{grid-column:1/-1}.profile>.section-title:nth-of-type(1),.profile>.attributes{grid-column:1}.profile>.section-title:nth-of-type(2),.profile>.relic{grid-column:2}.profile>.section-title:nth-of-type(1),.profile>.section-title:nth-of-type(2){grid-row:8}.profile>.attributes,.profile>.relic{grid-row:9}.class-switch{margin-bottom:2px}.right-rail{padding:14px}.arena-card{margin-bottom:3px}}

'use strict';
(() => {
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const classes = {
    swordsman:{name:'Swordsman',icon:'⚔',color:'#b8d5a5',skills:[['Whirlwind Slash','360° close-range strike'],['Iron Guard','Restore health & resist'],['Lunging Blade','Close the distance'],['Rallying Cry','Power up nearby allies']]},
    wizard:{name:'Wizard',icon:'✧',color:'#a7c7ed',skills:[['Fireball','Explosive elemental blast'],['Frost Nova','Freeze nearby creatures'],['Arcane Bolt','Piercing magic missile'],['Mana Surge','Restore energy & empower']]},
    ninja:{name:'Ninja',icon:'☯',color:'#d2a7dd',skills:[['Shadow Strike','Blink to a nearby foe'],['Phantom Clones','Strike in a wide arc'],['Venom Blade','Poison your target'],['Smoke Veil','Dodge & recover']]},
    archer:{name:'Archer',icon:'➶',color:'#e4cb8a',skills:[['Piercing Shot','Arrow through the line'],['Snare Trap','Root the closest foe'],['Multi-shot','Five-arrow volley'],['Storm Focus','Rapid-fire for a moment']]}
  };
  const stats={str:10,dex:10,int:10,vit:10};
  const player={x:0,y:0,r:13,hp:100,maxHp:100,energy:60,maxEnergy:60,speed:150,level:1,xp:0,nextXp:80,skillPoints:0,attackAt:0,invuln:0,auto:false,aim:{x:1,y:0},buff:0};
  let W=600,H=440,dpr=1,last=0,worldTime=0,paused=false,levelPending=false,attackHeld=false,attackTarget=null,moveTarget=null,toastTimer=0,questKills=0;
  let enemies=[],particles=[],projectiles=[],keys=new Set(),cooldowns=[0,0,0,0],loot=[];
  let classKey='swordsman';
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=Math.max(1,r.width);H=Math.max(1,r.height);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!player.x){player.x=W/2;player.y=H/2;spawnInitial()}}
  new ResizeObserver(resize).observe(canvas);
  function spawnInitial(){for(let i=0;i<4;i++)spawnEnemy()}
  function spawnEnemy(){const angle=rand(0,Math.PI*2),distance=rand(Math.min(W,H)*.34,Math.min(W,H)*.47);enemies.push({x:clamp(player.x+Math.cos(angle)*distance,22,W-22),y:clamp(player.y+Math.sin(angle)*distance,22,H-22),r:12,hp:40+player.level*4,maxHp:40+player.level*4,speed:rand(22,34),attackAt:0,hit:0,poison:0,freeze:0,type:Math.random()<.25?'brute':'wisp'})}
  function setClass(k){classKey=k;const c=classes[k];$('#className').textContent=c.name.toUpperCase();$('#portraitIcon').textContent=c.icon;$('#classSelect').value=k;$('#skillList').innerHTML=c.skills.map((s,i)=>`<div class="skill" id="skill${i}"><div class="skill-key">${i+1}</div><div><b>${s[0]}</b><small>${s[1]}</small></div><span class="cooldown" id="cool${i}">READY</span></div>`).join('');toast(`${c.name} selected`)}
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}
  function setAim(x,y){const dx=x-player.x,dy=y-player.y,l=Math.hypot(dx,dy)||1;player.aim={x:dx/l,y:dy/l}}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(30,120);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.55),max:.55,color})}}
  function attack(now){if(now<player.attackAt)return;player.attackAt=now+(classKey==='archer'||classKey==='wizard'?0.48:0.62);const c=classes[classKey];const range=classKey==='swordsman'||classKey==='ninja'?58:245;let target=enemies.filter(e=>dist(e,player)<range).sort((a,b)=>dist(a,player)-dist(b,player))[0];if(target&&classKey!=='swordsman'&&classKey!=='ninja'){fire(player.x,player.y,target.x,target.y,c.color,1,11)}else if(target){const a=Math.atan2(target.y-player.y,target.x-player.x);for(const e of enemies){if(dist(e,player)<66&&Math.cos(Math.atan2(e.y-player.y,e.x-player.x)-a)>.1)damage(e,14+stats.str*.7,c.color)}}else if(classKey==='wizard'||classKey==='archer'){fire(player.x,player.y,player.x+player.aim.x*range,player.y+player.aim.y*range,c.color,1,11)}else{burst(player.x+player.aim.x*24,player.y+player.aim.y*24,c.color,3)}}
  function fire(x,y,tx,ty,color,power=1,size=7){const a=Math.atan2(ty-y,tx-x);projectiles.push({x:x+Math.cos(a)*16,y:y+Math.sin(a)*16,vx:Math.cos(a)*330,vy:Math.sin(a)*330,life:.8,damage:13+stats.dex*.5,range:255,power,color,size})}
  function damage(e,amount,color){if(!enemies.includes(e))return;e.hp-=amount;e.hit=.12;burst(e.x,e.y,color,3);if(e.hp<=0)kill(e)}
  function kill(e){const i=enemies.indexOf(e);if(i<0)return;enemies.splice(i,1);burst(e.x,e.y,'#d7c58c',13);player.xp+=24+Math.round(player.level*2);questKills++;$('#questCount').textContent=`${Math.min(questKills,5)} / 5`;$('#questFill').style.width=`${Math.min(questKills,5)*20}%`;if(Math.random()<.6)dropLoot();while(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.floor(player.nextXp*1.12+16);player.skillPoints+=5;player.maxHp+=8;player.hp=player.maxHp;player.maxEnergy+=3;player.energy=player.maxEnergy;openLevel()}if(enemies.length<6)spawnEnemy();updateHud()}
  function dropLoot(){const tiers=[['COMMON','common'],['UNCOMMON','uncommon'],['RARE','rare'],['MYTHIC','mythic'],['LEGENDARY','legendary'],['ANCIENT','ancient'],['CELESTIAL','celestial']];const weights=[48,26,14,7,3,1.5,.5];let roll=Math.random()*100,t=tiers[0];for(let i=0;i<tiers.length;i++){roll-=weights[i];if(roll<=0){t=tiers[i];break}}const item=`${['Wanderer','Hollow','Verdant','Dawn','Wayfarer'][Math.floor(Math.random()*5)]} ${['Charm','Sigil','Tunic','Band'][Math.floor(Math.random()*4)]}`;loot.unshift({item,tier:t[0],cls:t[1]});loot=loot.slice(0,5);renderLoot();$('#relicName').textContent=item;$('#relicDetail').textContent=`${t[0]} · +${Math.ceil(Math.random()*8)}% ${['damage','vitality','haste'][Math.floor(Math.random()*3)]}`;$('#relicDetail').className=`rarity-${t[1]}`}
  function renderLoot(){$('#lootList').innerHTML=loot.length?loot.map(x=>`<div class="loot-item"><span class="rarity-${x.cls}">${x.item}</span><small>${x.tier}</small></div>`).join():'<div class="empty">Defeat a creature to find loot.</div>'}
  function openLevel(){levelPending=true;$('#newLevel').textContent=player.level;$('#levelModal').hidden=false;paused=true}
  const statInfo={str:['Strength','Physical damage & defense'],dex:['Dexterity','Attack, movement & critical rate'],int:['Intelligence','Elemental damage & cooldowns'],vit:['Vitality','Maximum health & regeneration']};
  $('#attributeChoices').innerHTML=Object.entries(statInfo).map(([k,v])=>`<button class="attribute-choice" data-stat="${k}"><b>${k.toUpperCase()} · ${v[0]}</b><small>${v[1]}</small></button>`).join('');
  $('#attributeChoices').addEventListener('click',e=>{const b=e.target.closest('[data-stat]');if(!b)return;allocate(b.dataset.stat);$('#levelModal').hidden=true;levelPending=false;paused=false;updateHud()});
  function allocate(k){stats[k]++;if(k==='vit'){player.maxHp+=10;player.hp=Math.min(player.maxHp,player.hp+10)}if(k==='int'){player.maxEnergy+=5;player.energy=player.maxEnergy}}
  $('#continueBtn').onclick=()=>{if(levelPending){allocate('vit');$('#levelModal').hidden=true;levelPending=false;paused=false;updateHud()}};
  $('#autoBtn').onclick=()=>{player.auto=!player.auto;$('#autoBtn').textContent=`AUTO · ${player.auto?'ON':'OFF'}`;toast(player.auto?'Auto-allocate enabled':'Auto-allocate disabled')};
  $('#classSelect').onchange=e=>setClass(e.target.value);
  $('#lootClear').onclick=()=>{loot=[];renderLoot()};
  $('#pauseBtn').onclick=()=>{paused=!paused;$('#pauseBtn').textContent=paused?'▶':'Ⅱ';toast(paused?'Journey paused':'Journey resumed')};
